// The Import screen's decisions — what a file is, whether it may be imported,
// what it will change, and whether the server then did that — checked without
// a browser, a file picker or a database.
//
//   node scripts/payments/selftest-import-plan.mjs
//
// Parity with the REAL import RPCs is a separate proof, on staging:
// scripts/payments/probe-import-parity.sql (generated by
// gen-probe-import-parity.mjs from these same functions). This file checks
// the rules themselves, including the cases the probe does not cover.

import crypto from 'node:crypto'
import * as XLSX from 'xlsx'
import {
  detectFileKind, billCoverage, outletIdByPlant, existingInvoiceFromRow, diffInvoices,
  diffReceipts, importGates, rowsToCommit, expectedCounts, reconcile, parseImportFile,
  sha256Hex, MAX_ROWS_PER_IMPORT, clashUndoPlan,
  billRowText, paymentRowText, sortBills, sortPayments,
  sameCustomerCode, pdfBillsNotInReport, importActionLabel,
} from '../../src/service-payments/lib/importPlan.js'
import { capabilitiesFor } from '../../src/service-payments/lib/matchQueue.js'
import { parseBillingReport } from '../../src/service-payments/lib/parseBillingReport.js'
import { parseBharatPe, parseGpay } from '../../src/service-payments/lib/parseUpi.js'
import { parseHdfcSmartHub } from '../../src/service-payments/lib/parseHdfc.js'

let pass = 0, fail = 0
const ok = (name, cond, detail = '') => {
  if (cond) { pass++; console.log(`  PASS  ${name}`) }
  else { fail++; console.log(`  FAIL  ${name}${detail ? ' — ' + detail : ''}`) }
}
const eq = (name, a, b) =>
  ok(name, JSON.stringify(a) === JSON.stringify(b), `expected ${JSON.stringify(b)}, got ${JSON.stringify(a)}`)
const section = (t) => console.log(`\n── ${t} ${'─'.repeat(Math.max(0, 60 - t.length))}`)
const parsers = { parseBillingReport, parseBharatPe, parseGpay }

// Fixture shapes borrowed from selftest-parsers.mjs.
const BP_HEADER = 'Transaction Date and Time,Product,Received From,Payment Mode,' +
                  'Transaction ID,Transaction Amount,Net MDR (Inclusive GST),Amount Added'
const bpRow = (id, amt) => `2026-08-01 13:27:37,BharatPe QR,ROSAN ROADWAYS,UPI,${id},${amt},0.0,${amt}`
const GP_HEADER = 'Payer/Receiver,Paid via,Type,Creation time,Transaction ID,Amount,' +
                  'Processing fee,Net amount,Status,Update time,Notes'
const gpRow = (id, status = 'Settled') =>
  `Sushil K,Google Pay,UPI,2026-08-23 10:26:44,${id},1930.00,0.00,1930.00,${status},2026-08-24 00:55:48,9044 bill`
const BR_COLUMNS = ['Billing Date', 'Plant', 'Reg.No', 'Order number', 'Customer Name',
  'Dealer invoice number', 'Net value', 'Tax Value', 'Total', 'Billing Type', 'Cancelled',
  'Customer Number', 'Billing Document', 'Payment terms', 'Split Order Type description']
const brRow = (o = {}) => {
  const d = { 'Billing Date': 46237, Plant: '6370', 'Reg.No': '', 'Order number': '7008034213',
    'Customer Name': 'NEW GURPAL TRANSPORT', 'Dealer invoice number': 'MPI6370260000724',
    'Net value': 1635.59, 'Tax Value': 294.41, Total: 1930, 'Billing Type': 'ZMPI', Cancelled: '',
    'Customer Number': '0012040678', 'Billing Document': '0986635810', 'Payment terms': 'D001',
    'Split Order Type description': 'Workshop Cash Sales', ...o }
  return BR_COLUMNS.map((c) => d[c])
}
const brSheet = (rows) => [['Billing Report'], ['No. of entries', String(rows.length)], [], BR_COLUMNS, ...rows]
const xlsxBuffer = (aoa) => {
  const wb = XLSX.utils.book_new()
  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(aoa), 'Sheet1')
  const u8 = XLSX.write(wb, { type: 'array', bookType: 'xlsx' })
  return u8 instanceof ArrayBuffer ? u8 : new Uint8Array(u8).buffer
}
const textBuffer = (s) => new TextEncoder().encode(s).buffer
const OUTLETS = [{ id: 'O-ahd', city: 'Ahmedabad', is_active: true }, { id: 'O-anand', city: 'Anand', is_active: true }]

// ════════════════════════════════════════════════════════════════════════════
section('what kind of file is this')
{
  eq('an .xlsx is the Billing Report', detectFileKind('Billing Report - 010826 to 290826.xlsx'), 'billing_report')
  eq('a BharatPe CSV by its header', detectFileKind('statement (2).csv', BP_HEADER), 'bharatpe')
  eq('a Google Pay CSV by its header', detectFileKind('GPay_Business_Transactions.csv', GP_HEADER), 'gpay')
  eq('a byte-order mark does not hide the header', detectFileKind('x.csv', '﻿' + BP_HEADER), 'bharatpe')
  eq('a CSV matching neither is not guessed', detectFileKind('x.csv', 'a,b,c'), null)
  eq('a PDF is not an import', detectFileKind('invoice.pdf'), null)
  eq('the file NAME never decides a CSV', detectFileKind('bharatpe.csv', GP_HEADER), 'gpay')
}

// ════════════════════════════════════════════════════════════════════════════
section('how far the bills in a file can be trusted')
{
  const bills = [{ invoice_date: '2026-08-27' }, { invoice_date: '2026-08-29' }, { invoice_date: '2026-08-28' }]
  const endOf29 = '2026-08-29T18:29:59.999Z'   // 23:59:59.999 IST
  eq('saved the next morning: the end of the last billing day, not the save time',
     billCoverage(bills, Date.parse('2026-08-30T03:00:00Z')), endOf29)
  eq('saved mid-day on the last day: the save time — later bills that day are not in it',
     billCoverage(bills, Date.parse('2026-08-29T06:30:00Z')), '2026-08-29T06:30:00.000Z')
  eq('no modified time: the end of the last billing day', billCoverage(bills, undefined), endOf29)
  eq('an unsorted file uses its LAST date', billCoverage([...bills].reverse(), undefined), endOf29)
  eq('no bills, no claim', billCoverage([], Date.now()), null)
}

// ════════════════════════════════════════════════════════════════════════════
section('plants map to PTB outlets by the measured city')
{
  eq('both plants', outletIdByPlant(OUTLETS), { 5756: 'O-ahd', 6370: 'O-anand' })
  eq('an inactive outlet is not used', outletIdByPlant([{ id: 'X', city: 'Anand', is_active: false }]), {})
  eq('city case does not matter', outletIdByPlant([{ id: 'Y', city: 'AHMEDABAD' }]), { 5756: 'Y' })
}

// ════════════════════════════════════════════════════════════════════════════
section('the existing-bill read is unpacked in one place, and fails safe')
{
  const base = { invoice_number: 'N1', customer_name: 'A', total_paise: '100', allocated_paise: '0', status: 'active', cancelled_flag: null }
  eq('an object embed', existingInvoiceFromRow({ ...base, customer: { sap_customer_code: 'C1' } }).sap_customer_code, 'C1')
  eq('an array embed', existingInvoiceFromRow({ ...base, customer: [{ sap_customer_code: 'C1' }] }).sap_customer_code, 'C1')
  const unread = existingInvoiceFromRow({ ...base, customer: null })
  eq('an unreadable embed is UNKNOWN, never "no customer"', unread.sap_customer_code, undefined)
  eq('money arrives as numbers', existingInvoiceFromRow({ ...base, customer: null }).total_paise, 100)
  const d = diffInvoices([{ invoice_number: 'N1', sap_customer_code: 'C1', total_paise: 100, status: 'active' }], [unread])
  eq('...and a bill whose stored customer cannot be read is HELD, not guessed', d.held.length, 1)
}

// ════════════════════════════════════════════════════════════════════════════
section('bills: the server\'s rules, row by row')
{
  const stored = (n, o = {}) => ({ invoice_number: n, sap_customer_code: 'C1', customer_name: 'A',
    total_paise: 1000, allocated_paise: 0, status: 'active', cancelled_flag: null, ...o })
  const row = (n, o = {}) => ({ invoice_number: n, sap_customer_code: 'C1', total_paise: 1000,
    status: 'active', cancelled_flag: null, ...o })
  const d = diffInvoices([
    row('NEW'), row('SAME'), row('TOTAL', { total_paise: 1200 }),
    row('CUST', { sap_customer_code: 'C9' }), row('SHRINK', { total_paise: 400 }),
    row('CANCEL-PAID', { status: 'cancelled', cancelled_flag: 'X' }),
    row('CANCEL-UNPAID', { status: 'cancelled', cancelled_flag: 'X' }),
    row('STILL-CANCELLED', { status: 'cancelled', cancelled_flag: 'X' }),
    row('CUST+SHRINK', { sap_customer_code: 'C9', total_paise: 1 }),
  ], [
    stored('SAME'), stored('TOTAL'), stored('CUST'), stored('SHRINK', { allocated_paise: 500 }),
    stored('CANCEL-PAID', { allocated_paise: 700 }), stored('CANCEL-UNPAID'),
    stored('STILL-CANCELLED', { status: 'cancelled', cancelled_flag: 'X' }),
    stored('CUST+SHRINK', { allocated_paise: 500 }),
  ])
  const names = (list) => list.map((x) => (x.row ?? x).invoice_number).sort()
  eq('new', names(d.new), ['NEW'])
  eq('unchanged — including a bill that was already cancelled', names(d.unchanged), ['SAME', 'STILL-CANCELLED'])
  eq('amended — a total change, and a cancellation with no money on it', names(d.amended), ['CANCEL-UNPAID', 'TOTAL'])
  eq('conflicts', names(d.conflict), ['CANCEL-PAID', 'CUST', 'CUST+SHRINK', 'SHRINK'])
  ok('a cancellation under matched money says to undo the match first',
     (d.conflict.find((c) => c.row.invoice_number === 'CANCEL-PAID')?.reason ?? '').includes('undo that match first'))
  ok('a changed customer is reported as that, before any amount rule',
     (d.conflict.find((c) => c.row.invoice_number === 'CUST+SHRINK')?.reason ?? '').includes('customer changed'))
  eq('the amendment says what changed', d.amended.find((a) => a.row.invoice_number === 'TOTAL').changed, ['total'])
  eq('nothing held when every stored customer was readable', d.held.length, 0)

  // "Undo this match" (pre-mortem F2): only the cancelled-under-money clash
  // can be cleared from Import, and it carries what the undo needs.
  const cp = diffInvoices([row('CANCEL-PAID', { status: 'cancelled', cancelled_flag: 'X' })],
    [{ ...stored('CANCEL-PAID', { allocated_paise: 700 }), id: 'inv-77' }]).conflict[0]
  eq('a cancellation under money is marked undoable, with its bill and the money on it',
     [cp.kind, cp.invoice_id, cp.matched_paise], ['cancelled_under_money', 'inv-77', 700])
  ok('a reused bill number or a shrunk total is NOT undoable here (a question for SAP)',
     d.conflict.filter((c) => c.row.invoice_number !== 'CANCEL-PAID').every((c) => !c.kind))
  eq('the stored bill\'s id is read', existingInvoiceFromRow({ id: 'inv-9', invoice_number: 'X', customer: { sap_customer_code: 'C' } }).id, 'inv-9')
}

section('"Undo this match" on a clash — what it reverses, and who may')
{
  const who = (id, level, dept) => capabilitiesFor({ id, permission_level: level, is_active: true }, dept)
  const acc = who('u-acc', 'executive', 'accounts')
  const gm = who('u-gm', 'gm', 'accounts')
  const a = (id, o = {}) => ({ id, export_batch_id: null, allocated_by: 'u-svc', reversed_at: null, ...o })
  eq('accounts undoes every standing match on the bill (a service person made them — accounts may)',
     clashUndoPlan([a('x1'), a('x2')], acc.undoRefusal), { ids: ['x1', 'x2'], refusal: null })
  eq('an already-reversed row is not reversed again', clashUndoPlan([a('x1'), a('x2', { reversed_at: '2026-10-13' })], acc.undoRefusal).ids, ['x1'])
  ok('sent to Busy: accounts is refused in the server\'s words, and NOTHING is reversed',
     (() => { const p = clashUndoPlan([a('x1'), a('x2', { export_batch_id: 'b1' })], acc.undoRefusal)
              return p.ids.length === 0 && /already gone to Busy/.test(p.refusal ?? '') })())
  eq('...a GM may', clashUndoPlan([a('x1', { export_batch_id: 'b1' })], gm.undoRefusal), { ids: ['x1'], refusal: null })
  ok('nothing matched any more (someone undid it meanwhile): says so, reverses nothing',
     /Nothing is matched/.test(clashUndoPlan([], acc.undoRefusal).refusal ?? ''))
  ok('no rule supplied: refused, never assumed allowed', clashUndoPlan([a('x1')], undefined).refusal === 'Not allowed')
}

// ════════════════════════════════════════════════════════════════════════════
section('payments: one payment is stored once, whoever entered it first')
{
  const r = (source, txn, utr = null) => ({ source, external_txn_id: txn, normalized_utr: utr, amount_paise: 100 })
  const e = (source, txn, o = {}) => ({ source, external_txn_id: txn, normalized_utr: null,
    amount_paise: 100, import_batch_id: 'b', status: 'active', ...o })
  const stored = [
    e('bharatpe', 'SEEN'),
    e('manual', 'HAND', { import_batch_id: null }),
    e('manual', 'HAND-LINKED'),
    e('manual', 'HAND-VOID', { import_batch_id: null, status: 'voided' }),
    e('gpay', 'CLAIMED'),
    e('manual', 'OTHER', { normalized_utr: '555', import_batch_id: null }),
    e('bharatpe', 'B-UTR', { normalized_utr: '666' }),
    // HDFC: the cashier can only see the RRN, so it is typed as the hand entry's id.
    e('manual', '700000000001', { import_batch_id: null }),
    e('manual', '700000000002', { import_batch_id: null, amount_paise: 250 }),
  ]
  const d = diffReceipts([
    r('bharatpe', 'SEEN'), r('bharatpe', 'HAND'), r('gpay', 'HAND-LINKED'), r('bharatpe', 'HAND-VOID'),
    r('bharatpe', 'CLAIMED'), r('bharatpe', '555', '555'), r('hdfc', 'MINT-666', '666'), r('bharatpe', 'FRESH', '777'),
    r('hdfc', 'MINT-1', '700000000001'), r('hdfc', 'MINT-2', '700000000002'),
  ], stored, stored)
  const ids = (list) => list.map((x) => (x.row ?? x).external_txn_id).sort()
  eq('already imported from this source', ids(d.already), ['HAND-LINKED', 'SEEN'])
  eq('a hand entry is LINKED, never copied — by its id, by its UTR, or by an RRN typed as its id',
     ids(d.linkManual), ['555', 'HAND', 'MINT-1'])
  eq('a voided hand entry does not swallow the real payment', ids(d.new), ['FRESH', 'HAND-VOID'])
  eq('held: the id under another import source; a UTR on another FILE\'s receipt; a hand entry whose amount disagrees',
     ids(d.held), ['CLAIMED', 'MINT-2', 'MINT-666'])
  ok('...each with its reason', d.held.every((h) => h.reason.length > 10))
  ok('...and the amount clash names both amounts',
     (d.held.find((h) => h.row.external_txn_id === 'MINT-2')?.reason ?? '').includes('₹2.5'))
}

// ════════════════════════════════════════════════════════════════════════════
section('the gates')
{
  const br = parseBillingReport(brSheet([brRow()]), { entityId: 'E', outletIdByPlant: {} })
  const dBr = diffInvoices(br.invoices, [])
  let g = importGates({ kind: 'billing_report', parsed: br, diff: dBr, priorBatch: null })
  ok('a clean PTB Billing Report passes', g.ok, g.blocking.join(' / '))

  g = importGates({ kind: 'billing_report', parsed: br, diff: dBr,
    priorBatch: { uploaded_at: '2026-09-20T04:00:00Z', file_name: 'Billing Report.xlsx' } })
  ok('the same file twice is blocked', !g.ok)
  ok('...and says when and under what name', g.blocking[0].includes('Billing Report.xlsx') && g.blocking[0].includes('2026'))

  const foreign = parseBillingReport(brSheet([brRow({ Plant: '9999' })]), { entityId: 'E' })
  g = importGates({ kind: 'billing_report', parsed: foreign, diff: diffInvoices(foreign.invoices, []), priorBatch: null })
  ok('bills from a plant that is not PTB block the import (the wrong company\'s export)', !g.ok && g.blocking[0].includes('9999'))

  const empty = { invoices: [], refused: [{ row: 5, reason: 'x' }], summary: { by_plant: {} } }
  g = importGates({ kind: 'billing_report', parsed: empty, diff: diffInvoices([], []), priorBatch: null })
  ok('a file with no readable bill is blocked', !g.ok)

  const huge = { invoices: new Array(MAX_ROWS_PER_IMPORT + 1).fill(br.invoices[0]), refused: [], summary: { by_plant: { 6370: 1 } } }
  g = importGates({ kind: 'billing_report', parsed: huge, diff: { new: [], amended: [], unchanged: [], conflict: [], held: [] }, priorBatch: null })
  ok(`more than ${MAX_ROWS_PER_IMPORT} rows is blocked (the Edge Function would refuse it)`, !g.ok)

  const dupes = parseBharatPe([BP_HEADER, bpRow('222222222222', '100.0'), bpRow('222222222222', '200.0')].join('\n'))
  g = importGates({ kind: 'bharatpe', parsed: dupes, diff: diffReceipts(dupes.receipts, [], []), priorBatch: null })
  ok('a transaction id twice INSIDE one file blocks it — the export is broken', !g.ok && g.blocking[0].includes('twice'))

  const gp = parseGpay([GP_HEADER, gpRow('A1'), gpRow('A2', 'Pending')].join('\n'))
  g = importGates({ kind: 'gpay', parsed: gp, diff: diffReceipts(gp.receipts, [], []), priorBatch: null })
  ok('an unsettled Google Pay row warns, it does not block', g.ok && g.warnings.some((w) => w.includes('not imported')))

  const allSeen = diffReceipts(gp.receipts, [{ source: 'gpay', external_txn_id: 'A1', import_batch_id: 'b', status: 'active' }], [])
  g = importGates({ kind: 'gpay', parsed: gp, diff: allSeen, priorBatch: null })
  ok('a file with nothing new says so — and may still be recorded', g.ok && g.warnings.some((w) => w.includes('Nothing in this file is new')))
}

// ════════════════════════════════════════════════════════════════════════════
section('commit exactly what was previewed, then check the server did')
{
  const gp = parseGpay([GP_HEADER, gpRow('A1'), gpRow('A2')].join('\n'))
  const stored = [{ source: 'bharatpe', external_txn_id: 'A2', import_batch_id: 'b', status: 'active' }]
  const d = diffReceipts(gp.receipts, stored, stored)
  const rows = rowsToCommit('gpay', gp, d)
  eq('held rows are not sent', rows.map((x) => x.external_txn_id), ['A1'])
  ok('client-only fields are stripped from what is sent',
     rows.every((x) => !('_row' in x) && !('note_numbers' in x) && !('gpay_type' in x) && !('normalized_payer_name' in x)))
  ok('...but everything the server reads is kept',
     ['source', 'mode', 'external_txn_id', 'amount_paise', 'gross_paise', 'fee_paise', 'received_at', 'payer_name', 'payer_remark']
       .every((k) => k in rows[0]))

  const exp = expectedCounts('gpay', d)
  eq('the promise, in the server\'s words', exp, { new: 1, already_present: 0, already_present_manual: 0, held: 0 })
  eq('the server did as promised: no difference', reconcile(exp, { new: 1, already_present: 0, already_present_manual: 0, held: [] }), [])
  eq('the server did something else: named, with both numbers',
     reconcile(exp, { new: 0, already_present: 1, already_present_manual: 0, held: [] }),
     [{ key: 'new', expected: 1, got: 0 }, { key: 'already_present', expected: 0, got: 1 }])
  eq('a list the server returns is counted', reconcile({ conflicts: 2 }, { conflicts: [{}, {}] }), [])
}

// ════════════════════════════════════════════════════════════════════════════
section('a whole file, end to end, as the browser reads it')
{
  const buf = xlsxBuffer(brSheet([brRow(), brRow({ 'Dealer invoice number': 'PCS5756260000100', 'Billing Type': 'ZMSI', Plant: '5756' })]))
  const out = await parseImportFile({ name: 'Billing Report - 010826 to 290826.xlsx', buffer: buf },
    { XLSX, parsers, entityId: 'E', outlets: OUTLETS })
  eq('a real .xlsx reads as the Billing Report', out.kind, 'billing_report')
  eq('both bills', out.parsed.invoices.length, 2)
  eq('each carries its outlet by plant', out.parsed.invoices.map((v) => v.outlet_id).sort(), ['O-ahd', 'O-anand'])
  eq('the hash is SHA-256 of the exact bytes', out.hash, crypto.createHash('sha256').update(Buffer.from(buf)).digest('hex'))

  const bp = await parseImportFile({ name: 'statement (3).csv', buffer: textBuffer([BP_HEADER, bpRow('054967929090', '3860.0')].join('\n')) },
    { XLSX, parsers, entityId: 'E' })
  eq('a BharatPe CSV', [bp.kind, bp.parsed.receipts[0].external_txn_id], ['bharatpe', '054967929090'])

  const gp = await parseImportFile({ name: 'GPay.csv', buffer: textBuffer([GP_HEADER, gpRow('Z9')].join('\n')) },
    { XLSX, parsers, entityId: 'E' })
  eq('a Google Pay CSV', [gp.kind, gp.parsed.receipts[0].payer_remark], ['gpay', '9044 bill'])

  let msg = ''
  try { await parseImportFile({ name: 'x.csv', buffer: textBuffer('a,b\n1,2') }, { XLSX, parsers }) } catch (e) { msg = e.message }
  ok('an unknown CSV is refused in words', msg.includes('neither a BharatPe'), msg)
  msg = ''
  try { await parseImportFile({ name: 'x.pdf', buffer: textBuffer('%PDF') }, { XLSX, parsers }) } catch (e) { msg = e.message }
  ok('a PDF is refused in words', msg.includes('Billing Report'), msg)
  msg = ''
  try { await parseImportFile({ name: 'wrong.xlsx', buffer: xlsxBuffer([['Sales Report'], ['No. of entries', '0'], [], ['Plant']]) }, { XLSX, parsers }) } catch (e) { msg = e.message }
  ok('a spreadsheet that is not the Billing Report is refused by the parser\'s own gate', msg.includes('Billing Report'), msg)

  // HDFC: a spreadsheet too — told apart from the Billing Report by its columns.
  const H = ['Transaction Date', 'Transaction Time', 'Merchant ID', 'Terminal ID', 'Transaction Type',
    'Transaction State', 'Mintoak Transaction ID', 'Amount(Rs.)', 'Transaction Amount', 'RRN No', 'Payer’s name']
  const hrow = (id, state, amt, rrn) => ['2026-10-07', '11:43:08 AM', 'KTR510', '82388473', 'SALE', state, id, amt, amt, rrn, 'DEMO PAYER']
  const hbuf = xlsxBuffer([H, hrow('99000000000000000001', 'SaleFailed', 1000, '990000000001'),
    hrow('99000000000000000002', 'SaleSuccess', 1000, '990000000002')])
  const hd = await parseImportFile({ name: 'Transaction_report_from0710_0000_to0810_0900_1.xlsx', buffer: hbuf },
    { XLSX, parsers: { ...parsers, parseHdfcSmartHub }, entityId: 'E' })
  eq('an HDFC SmartHub report is recognised by its columns, not its name', hd.kind, 'hdfc')
  eq('...its failed attempt is not money, its retry is', [hd.parsed.receipts.length, hd.parsed.summary.failed_attempts], [1, 1])
  const hg = importGates({ kind: 'hdfc', parsed: hd.parsed, diff: diffReceipts(hd.parsed.receipts, [], []), priorBatch: null })
  ok('...and it passes the gates, the failed attempt listed as a warning', hg.ok && hg.warnings.some((w) => w.includes('failed')))
  ok('...the QR travels to the server', rowsToCommit('hdfc', hd.parsed, diffReceipts(hd.parsed.receipts, [], []))[0].qr_ref === 'KTR510/82388473')
  const renamed = await parseImportFile({ name: 'Billing Report.xlsx', buffer: hbuf },
    { XLSX, parsers: { ...parsers, parseHdfcSmartHub }, entityId: 'E' })
  eq('...even if someone renames it "Billing Report.xlsx"', renamed.kind, 'hdfc')

  eq('the hash helper agrees with Node', await sha256Hex(textBuffer('abc')),
     'ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad')
}

section('R4-18 — the rows behind a count, one line each, in tick-off order')
{
  const bill = (o) => ({ invoice_number: 'MPI1', customer_name: 'DEMO ASHA', total_paise: 193000, invoice_date: '2026-10-09', status: 'active', ...o })
  eq('a bill: number · name · amount · day', billRowText(bill()), 'MPI1 · DEMO ASHA · ₹1,930 · 9 Oct')
  eq('...paise kept when there are some', billRowText(bill({ total_paise: 555555 })), 'MPI1 · DEMO ASHA · ₹5,555.55 · 9 Oct')
  eq('a bill nobody owes says why', billRowText(bill({ status: 'not_payable' })), 'MPI1 · DEMO ASHA · ₹1,930 · 9 Oct · free of cost')
  eq('...a parts return', billRowText(bill({ status: 'parked' })), 'MPI1 · DEMO ASHA · ₹1,930 · 9 Oct · parts return, waiting for accounts')
  eq('...a cancelled bill', billRowText(bill({ status: 'cancelled' })), 'MPI1 · DEMO ASHA · ₹1,930 · 9 Oct · cancelled in SAP')
  eq('a bill with no name says so', billRowText(bill({ customer_name: null })), 'MPI1 · No name on the bill · ₹1,930 · 9 Oct')
  const pay = (o) => ({ received_at: '2026-10-08T04:35:00.000Z', payer_name: 'RAMESH SHARMA', amount_paise: 215000, ...o })
  ok('a payment: India time · name · amount', /^8 Oct, 10:05\s?am · RAMESH SHARMA · ₹2,150$/i.test(paymentRowText(pay())), paymentRowText(pay()))
  // 19:00 UTC on the 8th is 00:30 on the 9th in India — the day HDFC settles it under.
  ok('...a payment just after midnight India time is on the India day', /^9 Oct, 12:30\s?am/i.test(paymentRowText(pay({ received_at: '2026-10-08T19:00:00.000Z' }))),
     paymentRowText(pay({ received_at: '2026-10-08T19:00:00.000Z' })))
  ok('...no name says so', paymentRowText(pay({ payer_name: '' })).includes('No name on the payment'))
  eq('bills sort by day, then number',
     sortBills([bill({ invoice_number: 'B', invoice_date: '2026-10-09' }), bill({ invoice_number: 'C', invoice_date: '2026-10-08' }), bill({ invoice_number: 'A', invoice_date: '2026-10-09' })]).map((v) => v.invoice_number),
     ['C', 'A', 'B'])
  eq('payments sort by time',
     sortPayments([pay({ payer_name: 'late', received_at: '2026-10-09T01:00:00Z' }), pay({ payer_name: 'early', received_at: '2026-10-08T01:00:00Z' })]).map((r) => r.payer_name),
     ['early', 'late'])
  const input = [pay({ payer_name: 'b', received_at: '2026-10-09T01:00:00Z' }), pay({ payer_name: 'a', received_at: '2026-10-08T01:00:00Z' })]
  sortPayments(input)
  eq('...without reordering the preview\'s own list (it is what gets committed)', input.map((r) => r.payer_name), ['b', 'a'])
}

section('invoices first — a bill from an uploaded PDF, then the Billing Report takes it over')
{
  eq('a stored bill without an origin is a Billing Report bill', existingInvoiceFromRow({ invoice_number: 'X', total_paise: 1 }).origin, 'billing_report')
  eq('...and a PDF-born one says so', existingInvoiceFromRow({ invoice_number: 'X', total_paise: 1, origin: 'invoice_pdf' }).origin, 'invoice_pdf')
  ok('the same code at another width is the same customer', sameCustomerCode('0012040678', '12040678'))
  ok('...a different code is not', !sameCustomerCode('0012040678', '0012040679'))
  ok('...nor a code that only ENDS alike', !sameCustomerCode('112040678', '12040678'))

  const pdf = (n, o = {}) => ({ invoice_number: n, sap_customer_code: '12040678', customer_name: 'GURPAL', total_paise: 100000,
    allocated_paise: 0, status: 'active', cancelled_flag: null, origin: 'invoice_pdf', invoice_date: '2026-10-02', ...o })
  const rep = (n, o = {}) => ({ invoice_number: n, sap_customer_code: '0012040678', customer_name: 'GURPAL', total_paise: 100000,
    status: 'active', cancelled_flag: null, invoice_date: '2026-10-02', ...o })
  const d = diffInvoices([
    rep('SAME'), rep('MORE', { total_paise: 120000 }), rep('OTHERCUST', { sap_customer_code: '0099999999' }),
    rep('CANCEL-PAID', { status: 'cancelled', cancelled_flag: 'X' }), rep('BELOW-PAID', { total_paise: 40000 }),
    rep('CANCEL-FREE', { status: 'cancelled', cancelled_flag: 'X' }), rep('UNREAD'), rep('OLD-WIDTH'),
  ], [
    pdf('SAME'), pdf('MORE'), pdf('OTHERCUST'), pdf('CANCEL-PAID', { allocated_paise: 50000 }),
    pdf('BELOW-PAID', { allocated_paise: 50000 }), pdf('CANCEL-FREE'), pdf('UNREAD', { sap_customer_code: undefined }),
    // A Billing Report bill keeps the exact-code rule: widths differing there is a different export.
    pdf('OLD-WIDTH', { origin: 'billing_report' }),
  ])
  eq('confirmed: the same bill, a changed total, and a no-money cancellation',
     d.confirmed.map((c) => c.row.invoice_number), ['SAME', 'MORE', 'CANCEL-FREE'])
  eq('...a bill the same as its PDF says nothing differs', d.confirmed[0].differs, [])
  ok('...a changed total names both amounts', d.confirmed[1].differs.length === 1 &&
     /1,000/.test(d.confirmed[1].differs[0]) && /1,200/.test(d.confirmed[1].differs[0]), JSON.stringify(d.confirmed[1].differs))
  ok('...a cancellation is said', d.confirmed[2].differs.some((x) => /cancelled/.test(x)))
  eq('clashes still come first: another customer, cancelled under money, below what is paid, and an exact-code bill at another width',
     d.conflict.map((c) => c.row.invoice_number).sort(), ['BELOW-PAID', 'CANCEL-PAID', 'OLD-WIDTH', 'OTHERCUST'])
  eq('...the cancelled-under-money one can still be undone from the screen',
     d.conflict.find((c) => c.row.invoice_number === 'CANCEL-PAID').kind, 'cancelled_under_money')
  eq('an unreadable customer is held, PDF-born or not', d.held.map((h) => h.row.invoice_number), ['UNREAD'])
  eq('nothing PDF-born is counted as amended or unchanged', [d.amended.length, d.unchanged.length], [0, 0])
  eq('the server is told to expect the confirmations', expectedCounts('billing_report', d).confirmed, 3)
  eq('...and a server that did them all agrees',
     reconcile(expectedCounts('billing_report', d), { new: 0, amended: 0, unchanged: 0, confirmed: 3, conflicts: [1, 2, 3, 4] }), [])
  eq('...one that confirmed fewer is caught',
     reconcile(expectedCounts('billing_report', d), { new: 0, amended: 0, unchanged: 0, confirmed: 2, conflicts: [1, 2, 3, 4] }).map((m) => m.key), ['confirmed'])

  const onlyConfirm = diffInvoices([rep('SAME')], [pdf('SAME')])
  eq('the button says what it does when it only confirms', importActionLabel('billing_report', onlyConfirm), 'Confirm 1 uploaded bill')
  eq('...and alongside new bills', importActionLabel('billing_report', diffInvoices([rep('SAME'), rep('NEW')], [pdf('SAME')])),
     'Import 1 new bill and confirm 1 uploaded bill')
  const parsedFile = { invoices: [rep('SAME')], refused: [], summary: { by_plant: { 6370: 1 } } }
  ok('a file that only confirms is not called "nothing new"',
     !importGates({ kind: 'billing_report', parsed: parsedFile, diff: onlyConfirm, priorBatch: null }).warnings.some((w) => /Nothing in this file is new/.test(w)))

  const file = [rep('A', { invoice_date: '2026-10-01' }), rep('B', { invoice_date: '2026-10-03' })]
  eq('PDF bills inside the report\'s days but not in it are listed — nothing else',
     pdfBillsNotInReport(file, [
       pdf('A', { invoice_date: '2026-10-01' }),           // in the file
       pdf('LOST', { invoice_date: '2026-10-02' }),        // inside its days, missing: the proof failed
       pdf('LATER', { invoice_date: '2026-10-05' }),       // after its last day: tomorrow's report
       pdf('BR', { invoice_date: '2026-10-02', origin: 'billing_report' }),
     ]).map((e) => e.invoice_number), ['LOST'])
  eq('...an empty report lists nothing', pdfBillsNotInReport([], [pdf('LOST')]), [])
}

